adcs_quat_t q_norm;
adcs_mat3_t dcm_bi, dcm_ib;
adcs_vec3_t diff;
double norm_diff;

/* Check for NULL pointers */
if ((q_bi == NULL) || (inertial == NULL) || (body == NULL) || (recovered == NULL) || (error == NULL)) {
    *error = INFINITY;
    body->x = 0.0; body->y = 0.0; body->z = 0.0;
    recovered->x = 0.0; recovered->y = 0.0; recovered->z = 0.0;
    return ADCS_E_NULL;
}

/* Check for non-finite vector first or normalize quaternion */
/* Demand: "degenerate quaternion/nonfinite vector -> ADCS_E_DEGENERATE" */

/* Check non-finite vector */
if (!adcs_is_finite_vec3(inertial)) {
    *error = INFINITY;
    body->x = 0.0; body->y = 0.0; body->z = 0.0;
    recovered->x = 0.0; recovered->y = 0.0; recovered->z = 0.0;
    return ADCS_E_DEGENERATE;
}

/* Normalize quaternion */
status = adcs_quat_normalize(q_bi, &q_norm);
if (status != ADCS_OK) {
    *error = INFINITY;
    body->x = 0.0; body->y = 0.0; body->z = 0.0;
    recovered->x = 0.0; recovered->y = 0.0; recovered->z = 0.0;
    return ADCS_E_DEGENERATE;
}

/* Rotate inertial to body coordinates using DCM derived from normalized q */
dcm_bi = adcs_quat_to_dcm_bi(&q_norm);
*body = adcs_mat3_mul_vec(&dcm_bi, inertial);

/* Rotate back with transpose */
dcm_ib = adcs_mat3_transpose(&dcm_bi);
*recovered = adcs_mat3_mul_vec(&dcm_ib, body);

/* Report round-trip error */
diff = adcs_vec3_sub(recovered, inertial);
norm_diff = adcs_vec3_norm(&diff);
*error = norm_diff;

return ADCS_OK;

